window.VF_SAINTS = [
["01-01","Sainte Marie, Mère de Dieu","Solennité","Marie","Ier siècle","L’Église célèbre Marie comme Mère de Jésus, vrai Dieu et vrai homme. Cette fête ouvre l’année civile sous le signe de l’Incarnation et de la paix.","Accueillir le Christ comme Marie, dans la foi et la disponibilité.","Marie, Mère de Dieu, conduis-moi vers ton Fils et apprends-moi à garder sa parole dans mon cœur."],
["01-02","Saint Basile le Grand et saint Grégoire de Nazianze","Mémoire","Docteurs de l’Église","IVe siècle","Deux évêques cappadociens, amis et grands théologiens, qui ont défendu la foi trinitaire et contribué à préciser le langage chrétien sur la divinité du Saint-Esprit.","Unir intelligence de la foi, amitié et vie spirituelle.","Saint Basile et saint Grégoire, apprenez-moi à chercher la vérité avec humilité et fidélité."],
["01-03","Le Saint Nom de Jésus","Mémoire facultative","Dévotion au Christ","Ier siècle","Le nom de Jésus signifie que Dieu sauve. La tradition chrétienne invoque ce nom comme confession de foi, prière et rappel de la proximité du Seigneur.","Revenir simplement au nom de Jésus dans la prière.","Jésus, que ton nom habite mon cœur et guide aujourd’hui mes paroles et mes actes."],
["01-07","Saint Raymond de Penyafort","Mémoire facultative","Prêtre","v. 1175–1275","Dominicain catalan, juriste et canoniste, il œuvra à l’organisation du droit de l’Église et au service pastoral de la réconciliation.","Mettre la compétence au service de la justice et de la miséricorde.","Saint Raymond, aide-moi à unir exigence de vérité et douceur envers les personnes."],
["01-13","Saint Hilaire de Poitiers","Mémoire facultative","Docteur de l’Église","v. 315–367","Évêque de Poitiers, théologien majeur de l’Occident latin, il défendit la foi en la divinité du Christ dans les controverses du IVe siècle.","Tenir la foi avec courage sans perdre la charité.","Saint Hilaire, affermis mon intelligence du Christ et mon courage dans la foi."],
["01-17","Saint Antoine, abbé","Mémoire","Père du désert","v. 251–356","Antoine d’Égypte est l’une des grandes figures du monachisme ancien. Sa vie de désert exprime la recherche d’un cœur unifié, libéré de ce qui disperse.","Créer du silence pour mieux discerner.","Saint Antoine, apprends-moi le détachement, la persévérance et la liberté intérieure."],
["01-20","Saint Fabien et saint Sébastien","Mémoire facultative","Martyrs","IIIe siècle","Fabien, pape, et Sébastien, martyr romain, représentent deux visages du témoignage chrétien dans les persécutions antiques.","Rester fidèle lorsque la foi coûte quelque chose.","Saints Fabien et Sébastien, donnez-moi une foi courageuse et sans haine."],
["01-21","Sainte Agnès","Mémoire","Vierge et martyre","IIIe–IVe siècle","Jeune martyre romaine, Agnès est devenue un symbole de fidélité au Christ et de liberté intérieure face aux pressions.","Choisir ce qui est juste même lorsque l’entourage pousse ailleurs.","Sainte Agnès, aide-moi à garder un cœur libre et fidèle."],
["01-22","Saint Vincent, diacre et martyr","Mémoire facultative","Martyr","† 304","Diacre de Saragosse, Vincent mourut martyr au début du IVe siècle. Son culte s’est rapidement répandu en Occident.","Servir sans séparer la foi des actes.","Saint Vincent, apprends-moi à servir avec constance et courage."],
["01-24","Saint François de Sales","Mémoire","Docteur de l’Église","1567–1622","Évêque de Genève-Annecy et auteur de l’Introduction à la vie dévote, il a montré que la sainteté est possible au cœur de la vie ordinaire.","Grandir dans la douceur et la fidélité quotidienne.","Saint François de Sales, donne-moi un cœur ferme, paisible et doux."],
["01-26","Saint Timothée et saint Tite","Mémoire","Évêques apostoliques","Ier siècle","Collaborateurs de saint Paul, Timothée et Tite apparaissent dans le Nouveau Testament comme responsables de jeunes communautés chrétiennes.","Transmettre la foi reçue avec fidélité et discernement.","Saint Timothée et saint Tite, apprenez-moi à transmettre la foi avec patience et vérité."],
["01-27","Sainte Angèle Merici","Mémoire facultative","Vierge consacrée","1474–1540","Fondatrice de la Compagnie de Sainte-Ursule, Angèle Merici s’est engagée pour l’éducation chrétienne des jeunes filles.","Faire grandir les autres par l’éducation et la confiance.","Sainte Angèle, apprends-moi à faire grandir ceux qui me sont confiés."],
["01-28","Saint Thomas d’Aquin","Mémoire","Docteur de l’Église","v. 1225–1274","Dominicain, philosophe et théologien, Thomas d’Aquin a profondément marqué la pensée catholique par sa recherche d’une harmonie entre foi et raison.","Chercher Dieu aussi avec l’intelligence.","Saint Thomas, donne-moi l’amour de la vérité et l’humilité devant le mystère."],
["01-31","Saint Jean Bosco","Mémoire","Prêtre éducateur","1815–1888","Fondateur des Salésiens, Don Bosco consacra sa vie à l’éducation et à l’accompagnement des jeunes, spécialement les plus pauvres.","Éduquer par la présence, la confiance et la joie.","Saint Jean Bosco, aide-moi à voir le potentiel de chaque jeune et à encourager plutôt qu’écraser."],

["02-02","Présentation du Seigneur","Fête","Fête du Seigneur","Ier siècle","Quarante jours après Noël, Jésus est présenté au Temple. Syméon le reconnaît comme lumière pour les nations.","Reconnaître la lumière du Christ dans l’ordinaire.","Seigneur Jésus, sois la lumière de mes choix et de mon chemin."],
["02-03","Saint Blaise","Mémoire facultative","Évêque et martyr","IVe siècle","Évêque de Sébaste en Arménie, Blaise est vénéré comme martyr de l’Antiquité chrétienne.","Confier à Dieu notre fragilité corporelle et notre témoignage.","Saint Blaise, prie pour les malades et affermis ma confiance en Dieu."],
["02-05","Sainte Agathe","Mémoire","Vierge et martyre","IIIe siècle","Martyre de Catane en Sicile, Agathe est l’une des saintes anciennes nommées dans la tradition liturgique romaine.","Demeurer digne et libre face à la violence.","Sainte Agathe, soutiens ceux qui subissent la violence et apprends-moi le courage."],
["02-06","Saint Paul Miki et ses compagnons","Mémoire","Martyrs du Japon","† 1597","Jésuite japonais, Paul Miki fut crucifié à Nagasaki avec vingt-cinq compagnons chrétiens.","Témoigner de l’Évangile sans haine envers les persécuteurs.","Saint Paul Miki et compagnons, apprenez-moi une fidélité courageuse et pacifique."],
["02-10","Sainte Scholastique","Mémoire","Moniale","v. 480–547","Sœur de saint Benoît selon la tradition, Scholastique est associée aux origines de la vie monastique bénédictine féminine.","Donner à la prière et à l’amitié spirituelle une vraie place.","Sainte Scholastique, apprends-moi la fidélité dans la prière et l’amour fraternel."],
["02-11","Bienheureuse Vierge Marie de Lourdes","Mémoire facultative","Marie","1858","Cette mémoire rappelle les apparitions reconnues de Lourdes et l’importance de la prière, de la conversion et de l’attention aux malades.","Porter les fragilités humaines dans l’espérance.","Notre-Dame de Lourdes, prie pour les malades et conduis-nous vers le Christ."],
["02-14","Saint Cyrille et saint Méthode","Mémoire facultative","Évangélisateurs","IXe siècle","Frères missionnaires auprès des peuples slaves, ils ont œuvré à l’annonce de l’Évangile dans les langues et cultures locales.","Annoncer sans mépriser les cultures.","Saints Cyrille et Méthode, apprenez-moi à transmettre l’Évangile avec intelligence et respect."],
["02-21","Saint Pierre Damien","Mémoire facultative","Docteur de l’Église","1007–1072","Ermite, cardinal et réformateur, Pierre Damien participa à un profond renouvellement de la vie ecclésiale au XIe siècle.","Réformer d’abord sa propre vie.","Saint Pierre Damien, aide-moi à conjuguer exigence, pénitence et charité."],
["02-23","Saint Polycarpe","Mémoire facultative","Évêque et martyr","v. 69–155","Évêque de Smyrne et témoin très ancien de la foi apostolique, Polycarpe mourut martyr à un âge avancé.","Rester fidèle jusqu’au bout.","Saint Polycarpe, affermis ma fidélité au Christ dans la durée."],
["02-27","Saint Grégoire de Narek","Mémoire facultative","Docteur de l’Église","v. 950–1003","Moine et poète arménien, Grégoire de Narek a laissé une œuvre de prière d’une grande profondeur sur la miséricorde et la conversion.","Transformer la pauvreté intérieure en prière.","Saint Grégoire de Narek, apprends-moi à parler à Dieu avec vérité et confiance."],

["03-04","Saint Casimir","Mémoire facultative","Prince","1458–1484","Prince de Lituanie et de Pologne, Casimir choisit une vie de foi, de simplicité et de service malgré son rang.","Ne pas laisser le statut social définir le cœur.","Saint Casimir, aide-moi à préférer la fidélité à Dieu au prestige."],
["03-07","Sainte Perpétue et sainte Félicité","Mémoire facultative","Martyres","† 203","Deux jeunes femmes martyrisées à Carthage. Le récit ancien de leur passion est l’un des témoignages chrétiens les plus marquants de l’Antiquité.","Soutenir la foi dans l’épreuve et la solidarité.","Saintes Perpétue et Félicité, donnez-moi courage et fidélité."],
["03-09","Sainte Françoise Romaine","Mémoire facultative","Religieuse","1384–1440","Épouse, mère puis fondatrice d’une communauté, Françoise Romaine unit responsabilités familiales, charité et vie spirituelle.","Chercher la sainteté dans plusieurs états de vie.","Sainte Françoise, apprends-moi à servir Dieu au cœur de mes responsabilités concrètes."],
["03-17","Saint Patrick","Mémoire facultative","Évêque missionnaire","Ve siècle","Missionnaire et évêque associé à l’évangélisation de l’Irlande, Patrick a profondément marqué le christianisme celtique.","Faire de son histoire personnelle un lieu de mission.","Saint Patrick, donne-moi confiance pour témoigner du Christ là où je suis envoyé."],
["03-18","Saint Cyrille de Jérusalem","Mémoire facultative","Docteur de l’Église","v. 315–386","Évêque de Jérusalem, il est célèbre pour ses catéchèses adressées aux futurs baptisés et aux nouveaux chrétiens.","Approfondir la foi au lieu de rester à la surface.","Saint Cyrille, donne-moi le goût d’une foi comprise, célébrée et vécue."],
["03-19","Saint Joseph","Solennité","Époux de Marie","Ier siècle","Époux de Marie et gardien de Jésus, Joseph est présenté comme un homme juste, capable d’écouter Dieu et d’agir concrètement.","Fidélité silencieuse, travail et responsabilité.","Saint Joseph, apprends-moi la fidélité dans les responsabilités ordinaires et la confiance quand tout n’est pas clair."],
["03-23","Saint Turibio de Mogrovejo","Mémoire facultative","Évêque","1538–1606","Archevêque de Lima, il parcourut son immense diocèse, organisa des synodes et défendit l’évangélisation respectueuse des populations locales.","Aller vers les personnes plutôt que gouverner de loin.","Saint Turibio, apprends-moi un service concret, juste et proche."],
["03-25","Annonciation du Seigneur","Solennité","Fête du Seigneur","Ier siècle","L’Annonciation célèbre le oui de Marie et surtout l’Incarnation : le Fils de Dieu assume réellement notre humanité.","Dire oui à Dieu dans la liberté.","Seigneur, rends-moi disponible à ta volonté, à l’exemple de Marie."],

["04-13","Saint Martin Ier","Mémoire facultative","Pape et martyr","† 655","Pape du VIIe siècle, Martin Ier fut exilé après avoir défendu la foi christologique de l’Église.","Tenir la vérité sans rechercher la puissance.","Saint Martin, donne-moi courage et fidélité lorsque la vérité a un coût."],
["04-21","Saint Anselme","Mémoire facultative","Docteur de l’Église","1033–1109","Moine, archevêque de Cantorbéry et penseur, Anselme a cherché à mieux comprendre par la raison la foi déjà reçue.","La foi cherche l’intelligence.","Saint Anselme, aide-moi à aimer Dieu de tout mon cœur et de toute mon intelligence."],
["04-23","Saint Georges et saint Adalbert","Mémoire facultative","Martyrs","IIIe et Xe siècles","Georges est un martyr ancien largement vénéré ; Adalbert de Prague fut évêque et missionnaire auprès des peuples d’Europe centrale.","Courage du témoignage et disponibilité missionnaire.","Saint Georges et saint Adalbert, apprenez-moi à servir le Christ avec courage."],
["04-24","Saint Fidèle de Sigmaringen","Mémoire facultative","Prêtre et martyr","1578–1622","Capucin et prédicateur, Fidèle mourut dans un contexte de fortes tensions confessionnelles en Europe.","Annoncer sans réduire l’autre à un adversaire.","Saint Fidèle, apprends-moi à défendre la foi avec vérité et charité."],
["04-25","Saint Marc","Fête","Évangéliste","Ier siècle","Marc est traditionnellement associé au deuxième Évangile, récit vif centré sur Jésus, le Messie crucifié et ressuscité.","Revenir à l’Évangile lui-même.","Saint Marc, donne-moi le goût de suivre Jésus concrètement et sans détour."],
["04-28","Saint Pierre Chanel","Mémoire facultative","Prêtre et martyr","1803–1841","Missionnaire mariste dans le Pacifique, Pierre Chanel mourut sur l’île de Futuna.","Persévérer dans une mission dont les fruits ne sont pas toujours visibles.","Saint Pierre Chanel, apprends-moi la patience et la confiance dans le service."],
["04-28","Saint Louis-Marie Grignion de Montfort","Mémoire facultative","Prêtre","1673–1716","Missionnaire français, il a fortement marqué la spiritualité mariale en l’orientant vers une consécration plus profonde au Christ.","Aller à Jésus avec Marie.","Saint Louis-Marie, apprends-moi une dévotion mariale qui conduise toujours au Christ."],
["04-29","Sainte Catherine de Sienne","Mémoire","Docteur de l’Église","1347–1380","Mystique dominicaine, conseillère de responsables religieux et politiques, Catherine a travaillé à l’unité de l’Église et à la réforme des mœurs.","Unir contemplation, courage et engagement.","Sainte Catherine, donne-moi un amour de l’Église lucide, exigeant et fidèle."],
["04-30","Saint Pie V","Mémoire facultative","Pape","1504–1572","Pape de la Réforme catholique après le concile de Trente, il œuvra à la réforme liturgique et pastorale.","Réformer les structures sans oublier la conversion personnelle.","Saint Pie V, aide-moi à rechercher la fidélité avec humilité."],

["05-01","Saint Joseph travailleur","Mémoire facultative","Travail et vie chrétienne","Ier siècle","Cette mémoire contemple saint Joseph dans le travail quotidien et rappelle la dignité du travail humain.","Travailler avec conscience sans faire du travail une idole.","Saint Joseph travailleur, accompagne mon travail et apprends-moi à servir par ce que je fais."],
["05-02","Saint Athanase","Mémoire","Docteur de l’Église","v. 296–373","Évêque d’Alexandrie, Athanase a défendu avec ténacité la pleine divinité du Christ.","Rester ferme sur l’essentiel tout en traversant les conflits.","Saint Athanase, affermis ma foi au Christ vrai Dieu et vrai homme."],
["05-09","Sainte Louise de Marillac","Mémoire facultative en France","Fondatrice","1591–1660","Avec saint Vincent de Paul, Louise de Marillac fonda les Filles de la Charité et développa un vaste service des pauvres et des malades.","Faire de la charité une organisation concrète, pas seulement un sentiment.","Sainte Louise de Marillac, apprends-moi une charité inventive et concrète."],
["05-12","Saint Nérée, saint Achille et saint Pancrace","Mémoire facultative","Martyrs","Antiquité","Martyrs anciens de Rome, honorés comme témoins de la fidélité chrétienne dans les premières générations.","Recevoir la foi comme un héritage transmis au prix d’un témoignage réel.","Saints martyrs de Rome, fortifiez ma fidélité au Christ."],
["05-13","Bienheureuse Vierge Marie de Fatima","Mémoire facultative","Marie","1917","Cette mémoire rappelle les apparitions reconnues de Fatima et l’appel à la prière, à la conversion et à la paix.","Prier pour la paix et convertir son propre cœur.","Notre-Dame de Fatima, apprends-moi la prière fidèle et le désir de paix."],
["05-18","Saint Jean Ier","Mémoire facultative","Pape et martyr","† 526","Pape du VIe siècle, Jean Ier mourut après avoir été emprisonné dans un conflit politique et religieux complexe.","Garder la conscience droite sous la pression politique.","Saint Jean Ier, donne-moi la force de ne pas sacrifier la vérité à la peur."],
["05-19","Saint Yves","Mémoire facultative en France","Prêtre","v. 1253–1303","Prêtre et juriste breton, Yves Hélory de Kermartin est connu pour son souci de justice et sa défense des pauvres.","Mettre le droit et la compétence au service des plus vulnérables.","Saint Yves, apprends-moi à rechercher une justice concrète et désintéressée."],
["05-20","Saint Bernardin de Sienne","Mémoire facultative","Prêtre","1380–1444","Franciscain et grand prédicateur italien, Bernardin contribua au renouveau spirituel du XVe siècle.","Parler de Dieu de manière compréhensible et vivante.","Saint Bernardin, aide-moi à annoncer le Christ avec clarté et joie."],
["05-21","Saint Christophe Magallanès et ses compagnons","Mémoire facultative","Martyrs","† 1927","Prêtres et laïcs mexicains tués durant les persécutions religieuses du début du XXe siècle.","Rester fidèle sans instrumentaliser la foi politiquement.","Saints martyrs du Mexique, donnez-moi une foi courageuse et pacifique."],
["05-22","Sainte Rita de Cascia","Mémoire facultative","Religieuse","v. 1381–1457","Épouse, mère puis religieuse augustinienne, Rita est associée à la patience dans l’épreuve et à la réconciliation.","Ne pas désespérer des situations difficiles.","Sainte Rita, accompagne ceux qui traversent les situations humaines les plus difficiles."],
["05-25","Bienheureuse Vierge Marie, Mère de l’Église","Mémoire","Marie","Ier siècle","Célébrée le lundi après la Pentecôte, Marie est honorée comme Mère de l’Église, présente au cœur de la communauté des disciples.","Vivre la foi dans la communion et la disponibilité à l’Esprit.","Marie, Mère de l’Église, garde-nous unis autour du Christ."],
["05-26","Saint Philippe Néri","Mémoire","Prêtre","1515–1595","Prêtre de Rome, fondateur de l’Oratoire, Philippe Néri est célèbre pour sa joie, son humour et son accompagnement spirituel.","Prendre Dieu au sérieux sans se prendre soi-même trop au sérieux.","Saint Philippe Néri, donne-moi une foi joyeuse, simple et fraternelle."],
["05-27","Saint Augustin de Cantorbéry","Mémoire facultative","Évêque missionnaire","† v. 604","Moine envoyé par le pape Grégoire le Grand pour évangéliser les Anglo-Saxons, il devint premier évêque de Cantorbéry.","Commencer humblement une mission nouvelle.","Saint Augustin de Cantorbéry, apprends-moi la patience dans les commencements."],
["05-29","Saint Paul VI","Mémoire facultative","Pape","1897–1978","Pape de 1963 à 1978, Paul VI mena à son terme le concile Vatican II et accompagna sa mise en œuvre.","Servir l’unité de l’Église dans les périodes de changement.","Saint Paul VI, aide-moi à unir fidélité, discernement et courage pastoral."],
["05-30","Sainte Jeanne d’Arc","Mémoire en France","Vierge","1412–1431","Jeune Française engagée dans la guerre de Cent Ans, Jeanne fut condamnée et exécutée à Rouen avant d’être réhabilitée. L’Église la vénère comme sainte.","Discerner sa mission sans confondre foi et ambition personnelle.","Sainte Jeanne d’Arc, apprends-moi le courage, la droiture et la fidélité à ma conscience."],

["06-01","Saint Justin","Mémoire","Martyr et philosophe","v. 100–165","Philosophe converti au christianisme, Justin a défendu la foi par le dialogue avec la philosophie de son temps avant de mourir martyr.","Expliquer la foi avec raison plutôt que par slogans.","Saint Justin, aide-moi à rendre compte de ma foi avec intelligence et respect."],
["06-02","Saint Marcellin et saint Pierre","Mémoire facultative","Martyrs","† v. 304","Martyrs romains de la persécution de Dioclétien, ils furent très tôt honorés dans la liturgie de Rome.","Recevoir la mémoire des témoins qui nous ont précédés.","Saints Marcellin et Pierre, fortifiez ma fidélité au Christ."],
["06-03","Saint Charles Lwanga et ses compagnons","Mémoire","Martyrs de l’Ouganda","† 1886","Jeunes chrétiens de la cour du royaume du Buganda, ils furent mis à mort pour leur foi et leur refus de certains abus.","Protéger la dignité et la conscience même sous pression.","Saint Charles Lwanga et compagnons, donnez-moi courage, pureté de cœur et fidélité."],
["06-05","Saint Boniface","Mémoire","Évêque et martyr","v. 675–754","Missionnaire anglo-saxon et évêque, Boniface joua un rôle majeur dans l’évangélisation et l’organisation de l’Église en Germanie.","Construire patiemment ce qui permettra à la foi de durer.","Saint Boniface, apprends-moi à bâtir avec persévérance et courage."],
["06-06","Saint Norbert","Mémoire facultative","Évêque","v. 1080–1134","Fondateur des Prémontrés, Norbert participa aux réformes ecclésiales du XIIe siècle.","Réformer sa vie avant de vouloir réformer les autres.","Saint Norbert, donne-moi cohérence entre ma foi et ma manière de vivre."],
["06-09","Saint Éphrem","Mémoire facultative","Docteur de l’Église","v. 306–373","Diacre syriaque, poète et théologien, Éphrem a transmis la foi par des hymnes et une théologie nourrie d’images bibliques.","Laisser la beauté conduire vers la vérité.","Saint Éphrem, apprends-moi à prier et comprendre par la beauté de la Parole."],
["06-11","Saint Barnabé","Mémoire","Apôtre","Ier siècle","Compagnon missionnaire de saint Paul, Barnabé est présenté dans les Actes comme un homme d’encouragement et de confiance.","Savoir reconnaître les dons des autres et leur donner une seconde chance.","Saint Barnabé, rends-moi capable d’encourager et de faire confiance."],
["06-19","Saint Romuald","Mémoire facultative","Abbé","v. 951–1027","Réformateur de la vie érémitique et monastique, Romuald est à l’origine de la tradition camaldule.","Retrouver l’essentiel dans le silence et la simplicité.","Saint Romuald, apprends-moi le silence qui ouvre à Dieu."],
["06-22","Saint Jean Fisher et saint Thomas More","Mémoire facultative","Martyrs","† 1535","Évêque et homme d’État anglais, ils furent exécutés après avoir refusé de poser un acte contraire à leur conscience religieuse.","Ne pas vendre sa conscience au pouvoir.","Saint Jean Fisher et saint Thomas More, donnez-moi une conscience droite et courageuse."],
["06-24","Nativité de saint Jean-Baptiste","Solennité","Prophète","Ier siècle","Jean-Baptiste prépare la venue de Jésus et appelle à la conversion. Sa mission consiste à désigner le Christ puis à s’effacer devant lui.","Préparer le chemin et ne pas chercher à prendre la place du Christ.","Saint Jean-Baptiste, apprends-moi à diminuer pour que le Christ grandisse."],
["06-27","Saint Cyrille d’Alexandrie","Mémoire facultative","Docteur de l’Église","v. 376–444","Patriarche d’Alexandrie et théologien, Cyrille joua un rôle majeur dans les débats sur l’unité de la personne du Christ.","Approfondir le mystère du Christ avec rigueur.","Saint Cyrille, affermis ma foi en Jésus, vrai Dieu et vrai homme."],
["06-29","Saint Pierre et saint Paul","Solennité","Apôtres","Ier siècle","Pierre et Paul représentent deux figures fondatrices de l’Église apostolique : le ministère d’unité et l’élan missionnaire.","Unir communion et mission.","Saint Pierre et saint Paul, affermissez ma foi et mon désir de témoigner."],
["06-30","Premiers martyrs de l’Église de Rome","Mémoire facultative","Martyrs","Ier siècle","Cette mémoire rassemble les chrétiens mis à mort à Rome sous Néron après l’incendie de la ville.","Ne pas oublier les témoins anonymes.","Premiers martyrs de Rome, priez pour tous les chrétiens persécutés et pour ma fidélité."],

["07-03","Saint Thomas","Fête","Apôtre","Ier siècle","Thomas passe du doute à la confession de foi devant le Christ ressuscité : « Mon Seigneur et mon Dieu ».","Ne pas avoir peur de présenter ses questions au Christ.","Saint Thomas, accompagne mes doutes et conduis-moi vers une foi plus personnelle."],
["07-04","Sainte Élisabeth du Portugal","Mémoire facultative","Reine","1271–1336","Reine du Portugal, elle est connue pour son engagement charitable et ses efforts de paix dans sa famille et son royaume.","Chercher la paix dans les conflits concrets.","Sainte Élisabeth, apprends-moi à devenir artisan de paix."],
["07-06","Sainte Maria Goretti","Mémoire facultative","Vierge et martyre","1890–1902","Jeune Italienne morte à douze ans après une agression sexuelle. Sa mémoire est associée au pardon et au respect de la dignité.","Protéger la dignité des personnes et refuser toute banalisation de la violence sexuelle.","Sainte Maria Goretti, prie pour les victimes de violence et pour une culture du respect."],
["07-09","Saint Augustin Zhao Rong et ses compagnons","Mémoire facultative","Martyrs de Chine","XVIIe–XXe siècles","Cette mémoire rassemble de nombreux martyrs de Chine, laïcs et consacrés, de différentes périodes de persécution.","Recevoir l’universalité de l’Église.","Saints martyrs de Chine, fortifiez ceux qui vivent leur foi dans des conditions difficiles."],
["07-20","Saint Apollinaire","Mémoire facultative","Évêque et martyr","Antiquité","Ancien évêque associé à Ravenne, Apollinaire est honoré comme martyr et témoin de l’évangélisation des premières communautés chrétiennes d’Italie.","Servir patiemment l’implantation de la foi.","Saint Apollinaire, donne-moi constance et courage apostolique."],
["07-21","Saint Laurent de Brindisi","Mémoire facultative","Docteur de l’Église","1559–1619","Capucin, prédicateur et diplomate, Laurent possédait une vaste culture biblique et linguistique.","Mettre l’étude au service de l’annonce et de la paix.","Saint Laurent de Brindisi, donne-moi le goût de l’Écriture et la sagesse dans les conflits."],
["07-22","Sainte Marie-Madeleine","Fête","Disciple du Seigneur","Ier siècle","Disciple de Jésus et témoin du tombeau vide, Marie-Madeleine est envoyée annoncer la Résurrection aux disciples.","Passer de la recherche du Christ à l’annonce du Christ vivant.","Sainte Marie-Madeleine, apprends-moi à chercher Jésus et à témoigner de sa Résurrection."],
["07-23","Sainte Brigitte de Suède","Mémoire facultative","Religieuse","v. 1303–1373","Épouse, mère puis fondatrice, Brigitte fut une grande figure spirituelle de l’Europe médiévale.","Unir vie familiale, responsabilité et profondeur spirituelle.","Sainte Brigitte, apprends-moi à chercher Dieu dans toutes les étapes de la vie."],
["07-24","Saint Charbel Makhlouf","Mémoire facultative","Prêtre et moine","1828–1898","Moine maronite libanais, Charbel vécut dans la prière, l’ascèse et la solitude.","Redécouvrir le silence et l’intériorité.","Saint Charbel, apprends-moi le silence, la prière fidèle et la disponibilité à Dieu."],
["07-25","Saint Jacques","Fête","Apôtre","Ier siècle","Jacques, fils de Zébédée, appartient au groupe proche de Jésus et fut l’un des premiers apôtres martyrs.","Suivre le Christ jusque dans le renoncement à la recherche de prestige.","Saint Jacques, apprends-moi le courage du chemin et la simplicité du service."],
["07-29","Sainte Marthe, sainte Marie et saint Lazare","Mémoire","Amis de Jésus","Ier siècle","La fratrie de Béthanie apparaît dans les Évangiles comme un lieu d’amitié, d’accueil, d’écoute et de foi en la Résurrection.","Accueillir le Christ dans sa maison et sa vie.","Sainte Marthe, sainte Marie et saint Lazare, apprenez-moi l’accueil, l’écoute et la foi."],
["07-30","Saint Pierre Chrysologue","Mémoire facultative","Docteur de l’Église","v. 380–450","Évêque de Ravenne, surnommé « parole d’or » pour la qualité et la concision de sa prédication.","Parler de Dieu avec clarté et sobriété.","Saint Pierre Chrysologue, apprends-moi une parole simple, vraie et féconde."],
["07-31","Saint Ignace de Loyola","Mémoire","Prêtre","1491–1556","Fondateur de la Compagnie de Jésus et auteur des Exercices spirituels, Ignace a développé une pédagogie du discernement et de la liberté intérieure.","Chercher comment Dieu travaille réellement dans sa vie.","Saint Ignace, apprends-moi à discerner ce qui conduit davantage à Dieu."],

["08-01","Saint Alphonse de Liguori","Mémoire","Docteur de l’Église","1696–1787","Évêque, moraliste et fondateur des Rédemptoristes, Alphonse a cherché une pastorale exigeante sans rigorisme écrasant.","Unir vérité morale et miséricorde.","Saint Alphonse, apprends-moi une conscience exigeante, paisible et confiante."],
["08-04","Saint Jean-Marie Vianney","Mémoire","Prêtre","1786–1859","Curé d’Ars, il consacra sa vie à la prière, à la prédication et surtout au ministère de la réconciliation.","Redécouvrir la force d’une présence fidèle et du pardon.","Saint Jean-Marie Vianney, apprends-moi la fidélité dans les petites choses et la confiance dans la miséricorde."],
["08-07","Saint Sixte II et ses compagnons","Mémoire facultative","Martyrs","† 258","Le pape Sixte II fut arrêté et exécuté avec plusieurs diacres pendant la persécution de Valérien.","Servir ensemble et rester unis dans l’épreuve.","Saint Sixte et compagnons, apprenez-moi la fidélité fraternelle."],
["08-07","Saint Gaëtan","Mémoire facultative","Prêtre","1480–1547","Fondateur des Théatins, Gaëtan s’engagea dans le renouveau spirituel du clergé et le service des pauvres.","Réformer par l’exemple plus que par les discours.","Saint Gaëtan, apprends-moi une foi concrète et réformatrice."],
["08-08","Saint Dominique","Mémoire","Prêtre","v. 1170–1221","Fondateur de l’Ordre des Prêcheurs, Dominique associa étude, prédication, pauvreté et vie communautaire.","Étudier pour mieux servir la vérité.","Saint Dominique, donne-moi le goût de la vérité et le désir de la transmettre avec charité."],
["08-10","Saint Laurent","Fête","Diacre et martyr","† 258","Diacre de Rome, Laurent fut martyrisé quelques jours après le pape Sixte II. La tradition souligne son service des pauvres.","Reconnaître les pauvres comme un trésor confié à l’Église.","Saint Laurent, apprends-moi à servir sans calcul et à mettre les personnes avant les biens."],
["08-11","Sainte Claire","Mémoire","Vierge","1193/94–1253","Compagne spirituelle de saint François d’Assise, Claire fonda une communauté féminine vivant radicalement la pauvreté évangélique.","Simplifier sa vie pour laisser plus de place à Dieu.","Sainte Claire, apprends-moi une liberté intérieure faite de simplicité et de confiance."],
["08-12","Sainte Jeanne-Françoise de Chantal","Mémoire facultative","Religieuse","1572–1641","Veuve et mère, elle fonda avec saint François de Sales l’ordre de la Visitation.","Transformer les épreuves de la vie en chemin de fécondité.","Sainte Jeanne de Chantal, apprends-moi à traverser les changements sans perdre confiance."],
["08-13","Saint Pontien et saint Hippolyte","Mémoire facultative","Martyrs","IIIe siècle","Pontien, pape, et Hippolyte, longtemps en opposition à Rome, moururent ensemble en exil : leur mémoire porte aussi un signe de réconciliation.","Laisser la réconciliation dépasser les anciennes divisions.","Saint Pontien et saint Hippolyte, apprenez-moi à préférer l’unité à l’orgueil."],
["08-14","Saint Maximilien Kolbe","Mémoire","Prêtre et martyr","1894–1941","Franciscain polonais, Maximilien Kolbe mourut à Auschwitz après s’être offert pour prendre la place d’un autre prisonnier.","Aimer concrètement, jusqu’au don de soi.","Saint Maximilien Kolbe, apprends-moi un amour plus fort que la peur et la haine."],
["08-15","Assomption de la Vierge Marie","Solennité","Marie","Ier siècle","La fête célèbre l’accomplissement de Marie auprès de Dieu et annonce l’espérance de la résurrection promise à l’humanité.","Vivre le présent à la lumière de la destinée éternelle.","Marie élevée auprès de Dieu, soutiens mon espérance et conduis-moi vers ton Fils."],
["08-19","Saint Jean Eudes","Mémoire facultative","Prêtre","1601–1680","Prêtre normand, fondateur et prédicateur, Jean Eudes développa la dévotion aux Cœurs de Jésus et de Marie et travailla à la formation du clergé.","Former le cœur autant que les compétences.","Saint Jean Eudes, apprends-moi à laisser le Christ former mon cœur."],
["08-20","Saint Bernard","Mémoire","Docteur de l’Église","1090–1153","Abbé cistercien de Clairvaux, Bernard fut prédicateur, théologien et grande figure du monachisme médiéval.","Unir amour du Christ, intériorité et discernement.","Saint Bernard, donne-moi un cœur qui cherche Dieu avec simplicité."],
["08-21","Saint Pie X","Mémoire","Pape","1835–1914","Pape de 1903 à 1914, Pie X encouragea notamment la communion fréquente et une participation plus profonde à la vie sacramentelle.","Recevoir les sacrements comme nourriture, pas comme formalité.","Saint Pie X, renouvelle en moi le désir de l’Eucharistie."],
["08-22","Bienheureuse Vierge Marie Reine","Mémoire","Marie","Ier siècle","Cette mémoire contemple Marie associée au règne du Christ, un règne de service, de justice et de miséricorde.","Comprendre l’autorité comme service.","Marie Reine, apprends-moi à servir avec humilité et fidélité."],
["08-24","Saint Barthélemy","Fête","Apôtre","Ier siècle","Barthélemy appartient au groupe des Douze apôtres envoyés par le Christ.","Se laisser appeler puis envoyer.","Saint Barthélemy, apprends-moi la disponibilité à l’appel du Christ."],
["08-25","Saint Louis","Mémoire facultative","Roi","1214–1270","Louis IX, roi de France, chercha à gouverner selon sa conscience chrétienne, avec un souci de justice et de service des pauvres.","Exercer les responsabilités avec conscience et justice.","Saint Louis, aide-moi à exercer toute responsabilité avec justice, sobriété et souci des plus faibles."],
["08-27","Sainte Monique","Mémoire","Mère de famille","v. 331–387","Mère de saint Augustin, Monique est connue à travers les Confessions pour sa prière persévérante et sa patience.","Persévérer sans vouloir contrôler la liberté des autres.","Sainte Monique, soutiens les parents qui prient pour leurs enfants et apprends-moi la patience."],
["08-28","Saint Augustin","Mémoire","Docteur de l’Église","354–430","Évêque d’Hippone, converti après une longue recherche, Augustin est l’un des penseurs majeurs du christianisme occidental.","Laisser Dieu rejoindre nos désirs profonds et convertir notre intelligence.","Saint Augustin, apprends-moi à chercher la vérité sans fuir mon propre cœur."],
["08-29","Martyre de saint Jean-Baptiste","Mémoire","Prophète et martyr","Ier siècle","Cette mémoire rappelle la mort de Jean-Baptiste pour avoir dénoncé une situation qu’il jugeait contraire à la loi de Dieu.","Dire la vérité avec courage sans rechercher le conflit.","Saint Jean-Baptiste, donne-moi courage, droiture et humilité."],

["09-03","Saint Grégoire le Grand","Mémoire","Pape et docteur de l’Église","v. 540–604","Pape, administrateur, pasteur et auteur spirituel, Grégoire contribua profondément à l’organisation et à la mission de l’Église en Occident.","Gouverner comme un service pastoral.","Saint Grégoire, apprends-moi à unir responsabilité, prière et souci concret des personnes."],
["09-05","Sainte Teresa de Calcutta","Mémoire facultative","Religieuse","1910–1997","Fondatrice des Missionnaires de la Charité, Teresa de Calcutta consacra sa vie au service des plus pauvres et des mourants.","Reconnaître une personne avant un problème.","Sainte Teresa, apprends-moi à voir et servir le Christ dans les personnes oubliées."],
["09-08","Nativité de la Bienheureuse Vierge Marie","Fête","Marie","Ier siècle","La fête célèbre la naissance de Marie, celle qui accueillera librement la venue du Christ.","Recevoir sa propre vie comme un appel.","Marie, apprends-moi à répondre avec confiance à ce que Dieu attend de moi."],
["09-09","Saint Pierre Claver","Mémoire facultative","Prêtre","1580–1654","Jésuite à Carthagène des Indes, Pierre Claver consacra son ministère aux Africains réduits en esclavage qui arrivaient dans le port.","Refuser l’indifférence face à la déshumanisation.","Saint Pierre Claver, rends-moi attentif à ceux que la société traite comme invisibles."],
["09-12","Le Saint Nom de Marie","Mémoire facultative","Marie","Ier siècle","Cette mémoire honore le nom de Marie dans la tradition de prière de l’Église.","Invoquer Marie pour rester tourné vers le Christ.","Marie, que ton nom me rappelle ta confiance en Dieu et ton oui fidèle."],
["09-14","La Croix glorieuse","Fête","Fête du Seigneur","Ier siècle","La fête contemple la Croix comme lieu du don total du Christ et de sa victoire par l’amour.","Ne pas glorifier la souffrance, mais l’amour qui traverse la souffrance.","Jésus crucifié et ressuscité, apprends-moi un amour fidèle jusque dans l’épreuve."],
["09-15","Notre-Dame des Douleurs","Mémoire","Marie","Ier siècle","Cette mémoire contemple Marie unie à la Passion de son Fils et proche des souffrances humaines.","Rester présent auprès de ceux qui souffrent.","Marie des douleurs, apprends-moi à ne pas fuir la souffrance des autres."],
["09-16","Saint Corneille et saint Cyprien","Mémoire","Évêques et martyrs","IIIe siècle","Le pape Corneille et l’évêque Cyprien de Carthage furent unis par l’amitié et les débats sur la réconciliation des chrétiens après les persécutions.","Allier fermeté, miséricorde et communion.","Saint Corneille et saint Cyprien, apprenez-moi à servir l’unité sans renoncer à la vérité."],
["09-17","Sainte Hildegarde de Bingen","Mémoire facultative","Docteur de l’Église","1098–1179","Abbesse, compositrice, auteure spirituelle et conseillère, Hildegarde fut une personnalité exceptionnelle du Moyen Âge.","Déployer ses dons sans séparer foi, intelligence et créativité.","Sainte Hildegarde, apprends-moi à mettre mes talents au service de la vérité et de la louange."],
["09-17","Saint Robert Bellarmin","Mémoire facultative","Docteur de l’Église","1542–1621","Jésuite, cardinal et théologien, Bellarmin fut une figure majeure de la Réforme catholique.","Argumenter avec rigueur sans perdre le sens spirituel.","Saint Robert Bellarmin, donne-moi rigueur, honnêteté et charité dans les débats."],
["09-19","Saint Janvier","Mémoire facultative","Évêque et martyr","IIIe–IVe siècle","Évêque de Bénévent selon la tradition, Janvier est un martyr particulièrement vénéré à Naples.","Se souvenir que la foi a traversé les siècles par des témoins concrets.","Saint Janvier, fortifie ma fidélité au Christ."],
["09-21","Saint Matthieu","Fête","Apôtre et évangéliste","Ier siècle","Matthieu est associé à l’appel du publicain et au premier Évangile dans l’ordre traditionnel.","Laisser l’appel du Christ rejoindre aussi ce qui paraît compromis dans notre vie.","Saint Matthieu, apprends-moi à me lever et à suivre le Christ sans rester prisonnier de mon passé."],
["09-23","Saint Pio de Pietrelcina","Mémoire","Prêtre","1887–1968","Capucin italien, Padre Pio consacra une grande part de son ministère à la confession, à l’Eucharistie et à l’accompagnement spirituel.","Revenir à la prière, au pardon et à la persévérance.","Saint Pio, aide-moi à chercher Dieu avec simplicité et persévérance."],
["09-26","Saint Côme et saint Damien","Mémoire facultative","Martyrs","Antiquité","Traditionnellement considérés comme médecins, Côme et Damien sont d’anciens martyrs très vénérés en Orient et en Occident.","Soigner sans réduire la personne à sa maladie.","Saints Côme et Damien, priez pour les malades et ceux qui prennent soin d’eux."],
["09-28","Saint Venceslas","Mémoire facultative","Martyr","v. 907–929","Duc de Bohême, Venceslas est vénéré comme souverain chrétien et martyr.","Exercer le pouvoir comme un service et non comme une possession.","Saint Venceslas, apprends-moi la justice et le courage dans les responsabilités."],
["09-29","Saint Michel, saint Gabriel et saint Raphaël","Fête","Archanges","Tradition biblique","Les trois archanges nommés dans l’Écriture évoquent le combat pour Dieu, l’annonce de sa parole et l’accompagnement dans la guérison.","Recevoir l’aide des anges sans les confondre avec Dieu.","Saints Michel, Gabriel et Raphaël, accompagnez-moi dans le combat de la foi, l’écoute de la Parole et le chemin de guérison."],
["09-30","Saint Jérôme","Mémoire","Docteur de l’Église","v. 347–420","Prêtre et grand érudit, Jérôme consacra une large part de sa vie à l’étude et à la traduction de la Bible.","Aimer l’Écriture assez pour l’étudier sérieusement.","Saint Jérôme, donne-moi le goût de la Parole de Dieu et la patience de l’étudier."],

["10-01","Sainte Thérèse de l’Enfant-Jésus","Mémoire","Docteur de l’Église","1873–1897","Carmélite de Lisieux, Thérèse a développé une spiritualité de confiance et d’abandon à l’amour miséricordieux de Dieu.","Faire les petites choses avec un grand amour.","Sainte Thérèse, apprends-moi ta petite voie de confiance et d’amour."],
["10-02","Saints Anges gardiens","Mémoire","Anges","Tradition chrétienne","Cette mémoire rappelle la conviction chrétienne de la sollicitude de Dieu, exprimée notamment par la mission des anges.","Vivre sous le regard de Dieu sans superstition.","Ange de Dieu, éclaire-moi, garde-moi, dirige-moi et conduis-moi."],
["10-04","Saint François d’Assise","Mémoire","Religieux","v. 1181–1226","Fondateur des Frères mineurs, François a choisi une vie de pauvreté évangélique, de fraternité et de paix.","Simplifier sa vie et fraterniser avec toute créature.","Saint François, apprends-moi la pauvreté de cœur, la paix et la joie de l’Évangile."],
["10-07","Notre-Dame du Rosaire","Mémoire","Marie","Tradition chrétienne","Cette mémoire invite à contempler avec Marie les mystères de la vie du Christ par la prière du Rosaire.","Laisser la répétition devenir contemplation.","Marie, apprends-moi à contempler Jésus avec fidélité."],
["10-14","Saint Callixte Ier","Mémoire facultative","Pape et martyr","IIIe siècle","Pape du IIIe siècle, Callixte est associé à une discipline pénitentielle plus ouverte à la réconciliation des pécheurs repentants.","Croire réellement à la possibilité du pardon.","Saint Callixte, apprends-moi à ne pas enfermer une personne dans son passé."],
["10-15","Sainte Thérèse de Jésus","Mémoire","Docteur de l’Église","1515–1582","Thérèse d’Avila, carmélite réformatrice, est une grande maîtresse de la prière intérieure et de l’amitié avec le Christ.","Faire de la prière une relation vivante et persévérante.","Sainte Thérèse, apprends-moi à persévérer dans l’amitié avec Dieu."],
["10-16","Sainte Marguerite-Marie Alacoque","Mémoire facultative","Vierge","1647–1690","Visitandine de Paray-le-Monial, elle est étroitement liée au développement de la dévotion au Sacré-Cœur de Jésus.","Contempler l’amour du Christ comme source de conversion.","Sainte Marguerite-Marie, aide-moi à répondre à l’amour du Christ par une vie plus fidèle."],
["10-17","Saint Ignace d’Antioche","Mémoire","Évêque et martyr","† v. 107","Évêque d’Antioche, Ignace écrivit plusieurs lettres sur son chemin vers le martyre à Rome, témoignant d’une foi très eucharistique et ecclésiale.","Aimer l’Église concrète, pas seulement idéale.","Saint Ignace, affermis mon attachement au Christ et à son Église."],
["10-18","Saint Luc","Fête","Évangéliste","Ier siècle","Auteur traditionnel du troisième Évangile et des Actes des Apôtres, Luc met fortement en lumière la miséricorde, la prière et l’Esprit Saint.","Lire l’histoire chrétienne comme une histoire de miséricorde et de mission.","Saint Luc, aide-moi à écouter l’Évangile avec un cœur disponible."],
["10-19","Saint Jean de Brébeuf, saint Isaac Jogues et leurs compagnons","Mémoire facultative","Martyrs missionnaires","XVIIe siècle","Missionnaires jésuites en Amérique du Nord, ils furent tués dans un contexte de guerres et de bouleversements culturels.","Annoncer le Christ sans idéaliser ni mépriser les cultures rencontrées.","Saints martyrs d’Amérique du Nord, apprenez-moi courage, respect et fidélité."],
["10-22","Saint Jean-Paul II","Mémoire facultative","Pape","1920–2005","Pape de 1978 à 2005, Jean-Paul II insista sur la dignité de la personne, l’appel à la sainteté, la nouvelle évangélisation et le dialogue.","Ne pas avoir peur d’ouvrir sa vie au Christ.","Saint Jean-Paul II, aide-moi à ne pas avoir peur de suivre le Christ."],
["10-23","Saint Jean de Capistran","Mémoire facultative","Prêtre","1386–1456","Franciscain et prédicateur, Jean de Capistran fut aussi engagé dans les conflits religieux et politiques de son temps.","Discerner comment témoigner sans se laisser absorber par les combats d’une époque.","Saint Jean de Capistran, donne-moi zèle et discernement."],
["10-24","Saint Antoine-Marie Claret","Mémoire facultative","Évêque","1807–1870","Missionnaire espagnol et fondateur des Clarétains, il fut prédicateur, évêque et promoteur de l’apostolat par l’édition.","Utiliser tous les moyens justes pour transmettre la foi.","Saint Antoine-Marie Claret, rends-moi créatif et fidèle dans l’annonce de l’Évangile."],
["10-28","Saint Simon et saint Jude","Fête","Apôtres","Ier siècle","Deux des Douze apôtres, célébrés ensemble comme témoins de l’appel et de la mission confiée par le Christ.","Accepter de servir même sans occuper le premier plan.","Saint Simon et saint Jude, soutenez ma fidélité à l’Évangile."],

["11-01","Tous les Saints","Solennité","Tous les saints","Tous les siècles","La Toussaint célèbre la multitude des saints connus et inconnus et rappelle l’appel universel à la sainteté.","Comprendre la sainteté comme vocation ordinaire de tout baptisé.","Tous les saints de Dieu, priez pour moi afin que je marche fidèlement vers le Christ."],
["11-02","Commémoration de tous les fidèles défunts","Commémoration","Défunts","Tous les siècles","L’Église prie pour les défunts dans l’espérance de la résurrection et de la communion définitive avec Dieu.","Faire mémoire dans l’espérance.","Donne-leur, Seigneur, le repos éternel, et que brille sur eux la lumière sans fin."],
["11-03","Saint Martin de Porrès","Mémoire facultative","Religieux","1579–1639","Dominicain péruvien de condition modeste, Martin de Porrès est connu pour son service des malades et des pauvres.","Servir sans chercher la reconnaissance.","Saint Martin de Porrès, apprends-moi une charité humble et concrète."],
["11-04","Saint Charles Borromée","Mémoire","Évêque","1538–1584","Archevêque de Milan, Charles Borromée joua un rôle important dans la mise en œuvre de la réforme catholique après le concile de Trente.","Réformer les institutions par une présence pastorale réelle.","Saint Charles, apprends-moi à unir organisation, exigence et proximité."],
["11-10","Saint Léon le Grand","Mémoire","Pape et docteur de l’Église","v. 400–461","Pape et grand théologien de l’Incarnation, Léon Ier contribua de manière décisive aux formulations du concile de Chalcédoine.","Confesser clairement qui est le Christ.","Saint Léon, affermis ma foi en Jésus-Christ vrai Dieu et vrai homme."],
["11-11","Saint Martin de Tours","Mémoire","Évêque","v. 316–397","Ancien soldat devenu moine puis évêque de Tours, Martin est célèbre pour son geste de partage du manteau avec un pauvre.","Voir le Christ dans celui qui a besoin d’aide.","Saint Martin, apprends-moi une charité concrète et immédiate."],
["11-12","Saint Josaphat","Mémoire","Évêque et martyr","v. 1580–1623","Évêque de rite byzantin uni à Rome, Josaphat travailla à l’unité ecclésiale et mourut dans un contexte de fortes tensions confessionnelles.","Chercher l’unité sans mépris de l’autre.","Saint Josaphat, apprends-moi à désirer l’unité avec vérité et charité."],
["11-16","Sainte Gertrude","Mémoire facultative","Religieuse","1256–v. 1302","Moniale bénédictine allemande, Gertrude la Grande a laissé des écrits mystiques centrés sur l’amour du Christ.","Faire de la connaissance de Dieu une relation intérieure.","Sainte Gertrude, apprends-moi la prière du cœur et la confiance."],
["11-17","Sainte Élisabeth de Hongrie","Mémoire","Religieuse","1207–1231","Princesse puis veuve, Élisabeth consacra une grande part de ses biens et de sa vie au service des pauvres et des malades.","Partager réellement et pas seulement symboliquement.","Sainte Élisabeth, apprends-moi une générosité qui transforme mes choix."],
["11-21","Présentation de la Vierge Marie","Mémoire","Marie","Tradition chrétienne","Cette mémoire, issue d’une ancienne tradition, contemple Marie entièrement offerte à Dieu.","Se rendre disponible à Dieu dès les petites choses.","Marie, apprends-moi à offrir librement ma vie à Dieu."],
["11-23","Saint Clément Ier","Mémoire facultative","Pape et martyr","Ier siècle","Clément est l’un des premiers évêques de Rome. Une ancienne lettre qui lui est attribuée témoigne du souci de communion entre Églises.","Servir l’unité dans les conflits communautaires.","Saint Clément, apprends-moi à rechercher la communion avec patience et vérité."],
["11-23","Saint Colomban","Mémoire facultative","Abbé missionnaire","v. 543–615","Moine irlandais, Colomban fonda plusieurs monastères en Europe continentale et contribua à la transmission du monachisme celtique.","Quitter ses habitudes pour servir une mission plus grande.","Saint Colomban, donne-moi liberté intérieure et courage missionnaire."],
["11-24","Saint André Dung-Lac et ses compagnons","Mémoire","Martyrs du Vietnam","XVIIe–XIXe siècles","Cette mémoire rassemble de nombreux martyrs vietnamiens, laïcs et ministres ordonnés, de différentes périodes de persécution.","Rester fidèle dans des contextes hostiles.","Saint André Dung-Lac et compagnons, priez pour les chrétiens persécutés et fortifiez ma foi."],
["11-25","Sainte Catherine d’Alexandrie","Mémoire facultative","Vierge et martyre","Antiquité","Martyre ancienne dont la tradition a fortement marqué l’Orient et l’Occident chrétiens.","Mettre intelligence et courage au service de la foi.","Sainte Catherine, donne-moi amour de la vérité et courage."],
["11-30","Saint André","Fête","Apôtre","Ier siècle","Frère de Pierre et l’un des premiers disciples appelés par Jésus, André apparaît aussi comme celui qui conduit d’autres personnes vers le Christ.","Répondre à l’appel et aider d’autres à rencontrer Jésus.","Saint André, apprends-moi à suivre le Christ et à conduire vers lui sans me mettre au centre."],

["12-03","Saint François Xavier","Mémoire","Prêtre missionnaire","1506–1552","Jésuite et compagnon d’Ignace de Loyola, François Xavier annonça l’Évangile en Inde, en Asie du Sud-Est et jusqu’aux portes de la Chine.","Sortir de son confort pour la mission.","Saint François Xavier, donne-moi zèle, respect et courage pour témoigner."],
["12-04","Saint Jean Damascène","Mémoire facultative","Docteur de l’Église","v. 675–749","Moine et théologien, Jean Damascène est notamment connu pour sa défense des saintes images dans la crise iconoclaste.","Comprendre que l’Incarnation donne une valeur nouvelle au visible.","Saint Jean Damascène, aide-moi à contempler le Christ avec intelligence et fidélité."],
["12-06","Saint Nicolas","Mémoire facultative","Évêque","IVe siècle","Évêque de Myre très populaire dans la tradition chrétienne, Nicolas est associé à la générosité envers les pauvres et les enfants.","Donner discrètement et sans rechercher d’image.","Saint Nicolas, apprends-moi une générosité joyeuse et discrète."],
["12-07","Saint Ambroise","Mémoire","Docteur de l’Église","v. 340–397","Évêque de Milan, Ambroise fut un grand prédicateur et joua un rôle décisif dans le cheminement de saint Augustin.","Unir responsabilité publique, culture et foi.","Saint Ambroise, donne-moi une parole juste et une foi courageuse."],
["12-08","Immaculée Conception de la Vierge Marie","Solennité","Marie","Ier siècle","Cette solennité célèbre Marie préservée du péché originel par grâce de Dieu en vue de sa mission de Mère du Christ.","Tout commence par la grâce de Dieu.","Marie Immaculée, apprends-moi à accueillir la grâce avec liberté et disponibilité."],
["12-11","Saint Damase Ier","Mémoire facultative","Pape","v. 305–384","Pape du IVe siècle, Damase soutint notamment le travail biblique de saint Jérôme et la mémoire des martyrs romains.","Transmettre la foi en prenant soin de ses sources et de sa mémoire.","Saint Damase, donne-moi le respect de la tradition vivante de l’Église."],
["12-12","Notre-Dame de Guadalupe","Mémoire facultative","Marie","1531","Cette mémoire mariale, profondément enracinée dans l’histoire du Mexique, est liée à saint Juan Diego et à l’évangélisation du continent américain.","Recevoir l’Évangile dans les cultures concrètes.","Notre-Dame de Guadalupe, accompagne les peuples des Amériques et apprends-moi une foi proche des petits."],
["12-13","Sainte Lucie","Mémoire","Vierge et martyre","† v. 304","Martyre de Syracuse, Lucie est devenue un symbole de lumière et de fidélité au Christ.","Garder une lumière intérieure dans les temps obscurs.","Sainte Lucie, garde en moi la lumière de la foi."],
["12-14","Saint Jean de la Croix","Mémoire","Docteur de l’Église","1542–1591","Carmélite, poète et mystique, Jean de la Croix a décrit le chemin de purification et d’union à Dieu, y compris à travers les nuits spirituelles.","Ne pas confondre absence de consolation et absence de Dieu.","Saint Jean de la Croix, apprends-moi à chercher Dieu au-delà de mes sensations."],
["12-21","Saint Pierre Canisius","Mémoire facultative","Docteur de l’Église","1521–1597","Jésuite, prédicateur et catéchiste, Pierre Canisius contribua fortement au renouveau catholique dans les pays germaniques.","Former la foi avec pédagogie et patience.","Saint Pierre Canisius, donne-moi le goût de transmettre clairement la foi."],
["12-23","Saint Jean de Kenty","Mémoire facultative","Prêtre","1390–1473","Prêtre et professeur à Cracovie, Jean de Kenty associa vie intellectuelle, prière et attention aux pauvres.","Ne pas séparer savoir et charité.","Saint Jean de Kenty, apprends-moi à unir connaissance, humilité et générosité."],
["12-25","Nativité du Seigneur","Solennité","Fête du Seigneur","Ier siècle","À Noël, l’Église célèbre la naissance de Jésus, le Verbe de Dieu fait chair.","Accueillir Dieu qui vient dans la petitesse.","Jésus, viens demeurer dans ma vie et apprends-moi la simplicité de Bethléem."],
["12-26","Saint Étienne","Fête","Premier martyr","Ier siècle","Étienne est présenté dans les Actes comme le premier martyr chrétien, témoin du Christ jusque dans la mort.","Témoigner sans répondre à la haine par la haine.","Saint Étienne, donne-moi courage et un cœur capable de pardonner."],
["12-27","Saint Jean","Fête","Apôtre et évangéliste","Ier siècle","Jean est associé au quatrième Évangile et à une contemplation profonde du mystère du Verbe incarné et du commandement de l’amour.","Demeurer dans l’amour du Christ.","Saint Jean, aide-moi à demeurer dans l’amour et à contempler plus profondément le Christ."],
["12-28","Saints Innocents","Fête","Martyrs","Ier siècle","La fête fait mémoire des enfants tués dans le récit de l’enfance de Jésus selon Matthieu et, par extension, des innocents victimes de la violence.","Refuser l’indifférence devant les victimes innocentes.","Seigneur, reçois les innocents victimes de la violence et rends-moi artisan de protection et de paix."],
["12-29","Saint Thomas Becket","Mémoire facultative","Évêque et martyr","1118–1170","Archevêque de Cantorbéry, Thomas Becket mourut dans un conflit entre pouvoir royal et liberté de l’Église.","Garder une conscience libre face au pouvoir.","Saint Thomas Becket, apprends-moi courage, prudence et fidélité."],
["12-31","Saint Sylvestre Ier","Mémoire facultative","Pape","† 335","Pape à l’époque de Constantin et du concile de Nicée, Sylvestre Ier vécut une période de profond changement pour le christianisme romain.","Traverser les changements sans perdre l’essentiel de la foi.","Saint Sylvestre, aide-moi à garder le Christ au centre lorsque les circonstances changent."]
].map((x,i)=>({id:i,key:x[0],name:x[1],rank:x[2],kind:x[3],period:x[4],bio:x[5],focus:x[6],prayer:x[7]}));